    },
    {
      "claim": "No L3 record provides affirmative threshold-relevant evidence for F <20% in the fasted query condition; antacid/MVI interaction records are condition-specific and not applicable.",
      "card_ids": ["C52", "C72", "C39"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "oral_auc_cmax_exposure",
